<template>
  <el-container>
    <el-header class="app-header"><AsideVue/></el-header>
    <el-main class="main-ctx classroom-home">
      <section class="hero">
        <div><span class="eyebrow">SMART LEARNING SUPERVISION</span><h1>智慧教室学习监管</h1><p>围绕学生慕课学习投入与答题诚信，形成学习时长、走神识别、行为异常和 AI 图片初筛的一体化视图。</p></div>
        <el-icon :size="82"><DataAnalysis/></el-icon>
      </section>
      <el-row :gutter="16" class="stats">
        <el-col :span="6"><el-card shadow="never"><span>参与学生</span><strong>{{ stats.studentCount }}</strong></el-card></el-col>
        <el-col :span="6"><el-card shadow="never"><span>慕课学习时长</span><strong>{{ duration(stats.learningDuration) }}</strong></el-card></el-col>
        <el-col :span="6"><el-card shadow="never"><span>疑似走神片段</span><strong>{{ stats.distractedCount }}</strong></el-card></el-col>
        <el-col :span="6"><el-card shadow="never" class="risk-card"><span>答题风险证据</span><strong>{{ stats.examRiskCount }}</strong></el-card></el-col>
      </el-row>
      <div class="module-grid">
        <el-card v-for="item in modules" :key="item.path" shadow="hover" class="module" @click="$router.push(item.path)">
          <div class="module-icon" :style="{background:item.background,color:item.color}"><el-icon :size="34"><component :is="item.icon"/></el-icon></div>
          <div><h3>{{ item.title }}</h3><p>{{ item.description }}</p><span>进入模块 →</span></div>
        </el-card>
      </div>
      <el-alert type="info" :closable="false" show-icon title="AI 识别结果属于辅助判断。走神和疑似手机搜题均需结合学习上下文及原始证据由教师复核。"/>
    </el-main>
  </el-container>
</template>

<script>
import axios from 'axios'
import AsideVue from '@/components/AsideVue.vue'
export default{
  name:'SmartClassroom',components:{AsideVue},data:()=>({stats:{studentCount:0,learningDuration:0,distractedCount:0,examRiskCount:0},modules:[
    {title:'3D 智慧教室',description:'三维课堂场景、机器人巡视与 A* 路径规划',icon:'VideoCamera',path:'/smart-classroom/3d',color:'#2f80ed',background:'#eaf3ff'},
    {title:'慕课学习监测',description:'查看学生学习时长、专注度及视频走神分析结果',icon:'Clock',path:'/smart-classroom/learning-monitor',color:'#16a085',background:'#e8f8f3'},
    {title:'答题行为记录',description:'汇总成绩、切屏异常、监控照片与手机检测结果',icon:'DocumentChecked',path:'/smart-classroom/exam-monitor',color:'#d97706',background:'#fff4df'}]}),created(){this.load()},methods:{
    async load(){try{const [learning,exam]=await Promise.all([axios.get('/api/learning/monitor',{params:{pageSize:1}}),axios.get('/api/exam/monitor',{params:{pageSize:1}})]);const l=learning.data.summary||{},e=exam.data.summary||{};this.stats={studentCount:Math.max(Number(l.student_count||0),Number(e.student_count||0)),learningDuration:Number(l.total_duration||0),distractedCount:Number(l.distracted_count||0),examRiskCount:Number(e.event_count||0)+Number(e.suspected_count||0)}}catch(e){console.error('学习监管概览加载失败',e)}},
    duration(v){const s=Number(v||0);const h=Math.floor(s/3600);const m=Math.floor(s%3600/60);return h?`${h}小时${m}分`:m?`${m}分钟`:`${Math.round(s)}秒`}
  }
}
</script>

